// Classic scripts keep `const` off `window`; t() and chat read these globally.
window.I18N_DICTIONARY = I18N_DICTIONARY;
window.SAKHI_KNOWLEDGE_BASE = SAKHI_KNOWLEDGE_BASE;

// Apply dictionary strings to static markup.
function applyLanguageToUI(lang) {
  if (!I18N_DICTIONARY[lang]) lang = "en";
  const dict = I18N_DICTIONARY[lang];
  const en = I18N_DICTIONARY.en;
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const value = dict[key] != null ? dict[key] : en[key];
    if (value != null) el.textContent = value;
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const key = el.getAttribute("data-i18n-placeholder");
    const value = dict[key] != null ? dict[key] : en[key];
    if (value != null) el.placeholder = value;
  });
  document.documentElement.lang = lang === "hinglish" ? "en" : lang;
}
window.applyLanguageToUI = applyLanguageToUI;
